  "structLogClear": "Limpiar",
  "structLogNote": "El escáner recuerda lo que detecta en este activo (rupturas de estructura y señales de velas) y lo conserva aquí aunque recargues la página. Lo resaltado en azul se vio por primera vez en las últimas 24h.",
