  "goldMode": "Oro",
  "cryptoMode": "Cripto",
  "forexMode": "Forex",
  "nasdaqMode": "Nasdaq",
  "ideskTitle": "La mesa institucional",
  "ideskIntro": "Un banco o fondo no «hace trading» como el retail: reparte el trabajo entre especialistas, con procesos, límites y tecnología. Aquí ves cómo funciona una mesa profesional por dentro y qué puedes robar de cada rol para operar como un profesional aunque estés solo en casa.",
  "discTitle": "Disciplina y rendimiento profesional",
  "discIntro": "Lo que separa al profesional rentable del retail que se quema no es el indicador secreto: es cómo gestionan su mente, sus errores y su estrés bajo presión. Esto es el «software» del trader de élite, prestado de mesas institucionales, pilotos, cirujanos y deportistas de alto rendimiento.",
  "mstTitle": "Stress test de margen",
  "mstIntro": "Antes de abrir una posición apalancada, comprueba si sobrevives a una caída fuerte. Mete tu saldo y tus posiciones y verás, escenario a escenario, cuánto pierdes, cuánto saldo te queda y si te salta el margin call o la liquidación. La pregunta clave: \"¿aguanto un −20 %?\".",
  "mstAccount": "Saldo de la cuenta",
  "mstMaintRate": "Margen de mantenimiento",
  "mstPosition": "Posición",
  "mstLong": "Largo",
  "mstShort": "Corto",
  "mstAddPosition": "Añadir posición",
  "mstGross": "Exposición bruta",
  "mstNet": "Exposición neta",
  "mstLeverage": "Apalancamiento",
  "mstNeutral": "Cartera neutral (largos y cortos se compensan): sin un movimiento direccional puro que dispare la liquidación. Ojo con el riesgo de base.",
  "mstLiqLabel": "Te liquidan con un movimiento de mercado de",
  "mstLiqSub": "aplicado a tu exposición neta (negativo = caída; positivo = subida)",
  "mstScenariosTitle": "Escenarios de mercado",
  "mstColMove": "Movimiento",
  "mstColPnl": "P&L",
  "mstColEquity": "Saldo tras el golpe",
  "mstColStatus": "Estado",
  "mstOk": "Aguanta",
  "mstCall": "Margin call",
  "mstLiq": "Liquidado",
  "mstCustom": "Escenario personalizado",
  "mstNote": "Modelo simplificado: un bróker real neteo por producto y aplica un margen de mantenimiento distinto según el activo (cripto ~0,5 %, CFD de índices/forex más alto). Úsalo para ver el ORDEN DE MAGNITUD del riesgo, no como cifra exacta de tu bróker. Lección: a más apalancamiento, más cerca está la liquidación de un movimiento normal de mercado.",
  "edgeUseJournal": "Usar mis datos del diario",
  "edgeLoaded": "Cargado desde {n} operaciones reales de tu diario",
  "edgeNoData": "Aún no tienes operaciones cerradas en el diario. Registra algunas y vuelve.",
  "edgeNotLogged": "Inicia sesión y registra operaciones en el diario para usar tus datos reales.",
  "edgeSampleWarn": "muestra pequeña, fiabilidad limitada (ideal ≥100 operaciones)",
  "tvSearchAsset": "Buscar activo…",
  "alertSymbolPh": "BTC, AAPL…",
  "ddrTitle": "Drawdown y recuperación",
  "ddrIntro": "La matemática del drawdown es asimétrica y cruel: perder un 50% exige ganar un 100% solo para volver al punto de partida. Esta calculadora te muestra cuánto necesitas recuperar y cuántas operaciones te costará con tu expectancy actual — la razón por la que los fondos profesionales recortan el tamaño en cuanto el drawdown supera su límite (normalmente 10-20%).",
  "ddrDrawdown": "Drawdown actual",
  "ddrExpectancy": "Expectancy por operación",
  "ddrRequired": "Ganancia necesaria para recuperar",
  "ddrRequiredSub": "sobre el capital restante, solo para volver a break-even",
  "ddrTrades": "Operaciones estimadas",
  "ddrTradesSub": "con tu riesgo y expectancy actuales, en compuesto (∞ = sin edge no se recupera jamás)",
  "ddrTableTitle": "Tabla: pérdida → ganancia necesaria",
  "ddrColDd": "Drawdown",
  "ddrColReq": "Recuperación necesaria",
  "ddrNote": "Política institucional: los fondos definen un drawdown máximo aceptable (p. ej. 15-20%) y reglas automáticas — a -10% se reduce el tamaño a la mitad, a -15% se para de operar y se revisa el sistema. Un VaR (valor en riesgo) diario limita cuánto puede perder la mesa en un día normal. Copia la idea: define TU límite antes de operar, no durante la caída.",
  "heatCorrLabel": "Correlación media entre posiciones",
  "heatEffective": "Riesgo efectivo ajustado",
  "heatEffectiveSub": "entre diversificación total (0%) y una sola gran operación (100%). Varios pares USD o varias tecnológicas ≈ 60-90%.",
  "gkTitle": "Griegas de opciones",
  "gkIntro": "Las griegas miden cómo cambia el precio de una opción cuando se mueve cada variable: subyacente, tiempo, volatilidad y tipos. Son el panel de instrumentos del trader de opciones — sin ellas vuelas a ciegas. Cada tarjeta incluye un ejemplo numérico; practica después con la calculadora Black-Scholes de la sección Opciones.",
  "mlqTitle": "Margen y liquidación en derivados",
  "mlqIntro": "Si operas futuros o perpetuos con apalancamiento, el margen es tu vida. La mayoría de cuentas no mueren por un mal análisis, sino por no entender CÓMO y CUÁNDO te liquida el exchange. Este módulo explica los modos de margen, los modos de posición, el precio de liquidación y cómo protegerte de las mechas de manipulación.",
  "ntTitle": "Operar noticias y eventos",
  "ntIntro": "Los datos de alto impacto (NFP, IPC, tipos) mueven el mercado en segundos. Saber qué hacer antes, durante y después separa una oportunidad de una cuenta quemada. Usa el calendario económico del Dashboard para saber cuándo llegan.",
  "smTitle": "Sentimiento de mercado",
  "smIntro": "Mide lo que siente la masa: miedo o codicia. En los extremos, el sentimiento es combustible contrarian — cuando TODOS son alcistas ya no queda nadie por comprar. Complementa al COT (posicionamiento real) que ya tienes en este pilar.",
  "imTitle": "Análisis intermercado",
  "imIntro": "Ningún mercado se mueve solo (John Murphy). Dólar, bonos, materias primas y bolsa están conectados: leer esas relaciones te da el contexto macro que confirma —o desmiente— tu operación. Es el 15% del examen CMT por algo.",
  "bcTitle": "Amplitud, ciclos y estacionalidad",
  "bcIntro": "Un índice puede subir sostenido por 5 valores gigantes mientras el resto se hunde: la amplitud mide la salud INTERNA del movimiento. Los ciclos y la estacionalidad añaden el 'cuándo' estadístico. Material de examen CMT que casi ningún retail mira.",
  "bkrTitle": "Brokers, regulación y estafas",
  "bkrIntro": "Puedes hacerlo todo bien en el gráfico y perderlo todo eligiendo mal dónde depositas. Este módulo te enseña a verificar un broker en 10 minutos y a reconocer las estafas que arrasan este sector.",
