  "rorTitle": "Riesgo de ruina",
  "rorIntro": "La probabilidad de que tu cuenta alcance una caída determinada en 500 operaciones, según tu ventaja y tamaño de apuesta. Monte Carlo sobre 5.000 simulaciones con tamaño fraccional fijo.",
  "rorWinRate": "Tasa de acierto",
