  "rorStreakP90": "peor caso (p90)",
  "rorExpectancy": "Expectativa por operación",
  "rorSimBasis": "basado en {n} simulaciones Monte Carlo",
  "rorVerdictNegative": "Expectativa negativa: con estos números la ruina no es un riesgo, es una certeza matemática a largo plazo. Antes de ajustar el riesgo, necesitas un sistema con ventaja.",
  "rorVerdictHigh": "Sistema con ventaja, pero el riesgo por operación es demasiado alto: la probabilidad de ruina sigue siendo seria. Baja el % por operación y observa cómo se desploma.",
  "rorVerdictOk": "Combinación sólida: ventaja positiva y riesgo controlado. Recuerda que la simulación asume disciplina perfecta — el stop se respeta siempre.",
  "rorRecoveryTitle": "La matemática de la recuperación: lo que pierdes vs. lo que necesitas ganar",
  "rorNote": "Incluso un sistema con esperanza positiva puede quebrar si apuestas demasiado. Reducir a la mitad el riesgo por operación baja el riesgo de ruina mucho más de lo que baja la rentabilidad.",
  "eduAcademyLabel": "Formación profesional",
