  "faqSubtitle_l004": "Las dudas más comunes antes de empezar.",
  "testimonial1Quote_l010": "Pasé de operar a ciegas a tener métricas claras de R/R, position size y win rate. Mi cuenta ya no sufre drawdowns brutales.",
  "testimonial1Author_l011": "Carlos M.",
  "testimonial1Role_l012": "Day Trader Cripto · 4 años",
  "testimonial2Quote_l020": "El Strategy Optimizer y el AI Coach me ahorran horas de análisis. Justifico el coste cada mes con una sola operación bien planeada.",
  "testimonial2Author_l021": "Ana R.",
  "testimonial2Role_l022": "Swing Trader Opciones",
  "testimonial3Quote_l030": "Llevo 8 meses usándolo a diario. El Monte Carlo y el journal cambiaron mi forma de ver el riesgo. 5 estrellas.",
  "testimonial3Author_l031": "David L.",
  "testimonial3Role_l032": "Trader Independiente · Forex",
  "faqQ1_l040": "¿Necesito ser experto para usarlo?",
  "faqA1_l041": "No. La app guía paso a paso cada calculadora y el Education Center cubre desde lo básico (qué es un Stop Loss) hasta estrategias avanzadas con opciones. Hay un Demo Trader gratuito para probarlo todo sin riesgo.",
  "faqQ2_l050": "¿Puedo cancelar la suscripción cuando quiera?",
  "faqA2_l051": "Sí. Cancela en 1 clic desde tu perfil. No hay permanencia. Si compras Lifetime, el acceso es permanente — sin pagos recurrentes.",
  "faqQ3_l060": "¿Qué activos están soportados?",
  "faqA3_l061": "Cripto, Forex, Acciones US (NYSE/NASDAQ), Índices (SPX, NDX, DAX, etc.), Materias Primas y Futuros. Los datos de cripto son en tiempo real; el resto pueden ir con retardo.",
  "faqQ4_l070": "¿La IA del Trade Coach es de pago aparte?",
  "faqA4_l071": "No. El AI Trade Coach (Claude) está incluido en todos los planes Premium. Analiza tu estrategia, identifica riesgos y sugiere mejoras como un mentor senior.",
  "faqQ5_l080": "¿Funciona en móvil?",
  "faqA5_l081": "Sí. Diseño responsive completo. Las calculadoras y el dashboard funcionan perfectamente en iOS/Android. App nativa en roadmap Q2.",
