  "smcTitle": "Smart Money / ICT",
  "optTitle": "Estrategias de opciones",
  "optIntro": "Combinar calls y puts te permite construir posiciones con riesgo definido y sacar partido no solo de la dirección, sino también de la volatilidad y el paso del tiempo. Usa la Calculadora de Opciones para ver las griegas y el diagrama de payoff de cada una.",
  "smcIntro": "El enfoque 'smart money' (popularizado por ICT) intenta seguir el rastro del dinero institucional: dónde acumulan órdenes, cómo cazan la liquidez del minorista y dónde vuelve el precio. Es discrecional: úsalo como confluencia, no como sistema mágico.",
  "ichiIntro": "Un 'gráfico de equilibrio de un vistazo' japonés, creado por Goichi Hosoda. Cinco líneas y una 'nube' proyectada muestran a la vez la tendencia, el soporte/resistencia, el momentum y las señales de entrada: está diseñado para leer el mercado de una sola mirada. Muy popular en forex y cripto.",
  "ewTitle": "Teoría de las Ondas de Elliott",
  "ewIntro": "Ralph Elliott observó que la psicología de masas mueve los mercados en patrones de ondas repetitivos. El precio avanza en una secuencia 'motriz' de 5 ondas en la dirección de la tendencia y luego corrige en una secuencia de 3 ondas en contra. La misma forma 5-3 se repite en cada grado, desde minutos hasta décadas.",
