  "wyckoffIntro": "El Método Wyckoff es un marco de análisis técnico desarrollado por Richard Wyckoff a principios del siglo XX. Estudia precio, volumen y tiempo para identificar los ciclos de manipulación de los grandes operadores institucionales (el Operador Compuesto) y operar en armonía con ellos.",
