  "heatTitle": "Calor del portafolio",
  "heatIntro": "Tu riesgo abierto total: lo que perderías si todas tus posiciones abiertas tocaran su stop a la vez. Limita esto, no solo el riesgo por operación.",
  "heatPosition": "Posición",
