  "heatWarn": "Subiendo. Un grupo de stops correlacionados podría doler; considera recortar.",
  "heatDanger": "Demasiado alto. Una mala sesión podría provocar una caída seria. Reduce tamaño o cierra posiciones.",
  "heatCorrelationNote": "Las posiciones correlacionadas (p. ej. varios pares con USD, o acciones tecnológicas) actúan como una sola operación grande: su riesgo combinado real es mayor que la suma mostrada aquí.",
  "streakTitle": "Probabilidad de rachas perdedoras",
  "streakIntro": "Incluso un gran sistema tiene rachas perdedoras largas. Esta es la probabilidad exacta de una racha de pérdidas consecutivas en tu muestra, para que no te sorprendan.",
  "streakTrades": "Número de operaciones",
