  "streakTableTitle": "Probabilidad de una racha de al menos…",
  "streakColLength": "Longitud de racha",
  "streakColProb": "Probabilidad",
  "streakNote": "Un sistema del 50% en 100 operaciones casi con seguridad tendrá una racha de 6-7 pérdidas. Dimensiona para que una racha normal nunca amenace tu cuenta.",
  "capitalAdvancedToolsTitle": "Análisis avanzado de riesgo",
  "wyckoffSchematicTitle": "Esquemas de Wyckoff",
  "wyckoffSchematicIntro": "La anatomía de manual de un rango de acumulación y uno de distribución, evento a evento, con las fases A-E.",
  "wyckoffAccSchematic": "Acumulación (luego subida)",
  "wyckoffDistSchematic": "Distribución (luego bajada)",
  "wyckoffReaccName": "Re-acumulación",
  "wyckoffReaccDesc": "Una pausa dentro de una tendencia alcista: el precio consolida, sacude a las manos débiles y reanuda la subida. Misma estructura que la acumulación pero dentro de una tendencia alcista.",
  "wyckoffRedistName": "Re-distribución",
  "wyckoffRedistDesc": "Una pausa dentro de una tendencia bajista: el precio consolida, atrapa a los compradores de ruptura y continúa cayendo. Misma estructura que la distribución pero dentro de una tendencia bajista.",
  "wyckoffLPSName": "LPS — Último punto de soporte",
