  "cotTitle": "Informe COT",
  "cotIntro": "El informe de Compromisos de Operadores (COT), publicado semanalmente por la CFTC de EE. UU., muestra cómo están realmente posicionados los mayores participantes en los mercados de futuros. Es lo más parecido que tiene el trader minorista a ver la mano del dinero institucional.",
