  "helpAria": "Ver explicación",
  "helpRiskPerTrade": "El porcentaje de la cuenta que estás dispuesto a perder EN ESTA operación, no en total. Lo habitual es entre el 1% y el 2%: con un 2% harían falta unas 35 pérdidas seguidas para dejar la cuenta a la mitad; con un 10% bastan 7.",
  "helpStopDistance": "La distancia entre la entrada y el stop es lo que determina el tamaño, no al revés. Un stop más ceñido permite comprar más unidades arriesgando lo mismo — pero también salta más veces.",
  "helpRequiredLeverage": "El apalancamiento que haría falta para abrir esa posición con tu capital. No es una recomendación: si sale muy alto, suele significar que el stop está demasiado lejos para tu cuenta, no que debas apalancarte.",
  "helpAccountBalance": "Usa el saldo real de hoy, no el que esperas tener. Todo el cálculo de riesgo se apoya en esta cifra, así que redondearla hacia arriba desplaza hacia arriba el tamaño de todas tus posiciones.",
  "helpPipValue": "Lo que gana o pierde la posición cuando el par se mueve un pip. Depende del par y de la divisa de tu cuenta: un pip de EURUSD no vale lo mismo que uno de USDJPY.",
  "helpLotSize": "Un lote estándar son 100.000 unidades de la divisa base; el mini son 10.000 y el micro 1.000. Un resultado de 0,35 lotes significa 35.000 unidades, no 35.",
  "helpLeverage": "Multiplica el resultado en las dos direcciones por igual. Con 10x, un movimiento del 10% en tu contra no te deja al 90%: te liquida. La liquidación llega antes que la pérdida total.",
  "helpContractSize": "Cada futuro representa una cantidad fija del subyacente, y no es la misma en todos. Un contrato del E-mini S&P mueve 50 $ por punto; uno de crudo, 1.000 barriles. Ese multiplicador es lo que convierte un movimiento pequeño en un resultado grande.",
  "helpSimulations": "Cuántas veces se reordenan tus operaciones al azar. Con pocas, el resultado cambia cada vez que pulsas; a partir de unas 5.000 los percentiles se estabilizan y ya puedes fiarte de ellos.",
  "helpDrawdown": "La mayor caída desde un máximo de la cuenta hasta el mínimo posterior. Es el número que de verdad decide si podrás seguir el sistema: casi nadie aguanta operando una racha que no esperaba.",
