  "structRefDisputed": "{n} nivel(es) quedan entre la cotización viva ({live}) y el último cierre ({close}): con una referencia son soporte y con la otra resistencia. El reparto de abajo usa la viva.",
  "gmbTitle": "Ludopatía y trading: dónde está la línea",
  "gmbFigTitle": "Por qué perder no apaga la conducta",
  "gmbFigIntro": "Dos rachas de doce operaciones con EXACTAMENTE el mismo número de ganadoras (verde). Sólo cambia el patrón: arriba, premio cada tres, previsible; abajo, premio impredecible.",
  "gmbFigFixed": "Premio previsible (cada 3)",
  "gmbFigVariable": "Premio impredecible — el mercado",
  "gmbFigNote": "Con premio previsible, dejas de tirar en cuanto deja de pagar. Con premio impredecible sigues mucho más tiempo, y sigues también cuando ya no paga: es el esquema más resistente a la extinción que se conoce. Las dos hileras ganan lo mismo; sólo una engancha.",
  "stratWinRateTag": "orientativo",
  "stratWinRateCaveat": "Rango orientativo del estilo, no una medición: no lleva muestra, ni periodo, ni fuente.",
  "stratWinRateNote": "Sobre las tasas de acierto de esta página: son rangos ORIENTATIVOS con los que se suele describir cada estilo, no resultados medidos. No llevan muestra, ni periodo, ni activo, ni fuente, así que no se pueden usar para dimensionar nada. Y aunque estuvieran medidas seguirían sin decir gran cosa solas: un 45 % con ganancias del triple que las pérdidas gana dinero, y un 70 % con pérdidas del triple que las ganancias lo pierde. Lo que decide es la esperanza —acierto × ganancia media − fallo × pérdida media—, no el porcentaje. La tuya sale de tu propio diario, no de esta tabla.",
  "xmTitle": "Margen cruzado: simulador de escalera",
  "calcDescCrossMargin": "Comprueba, tramo a tramo, si el bróker te dejará abrir la escalera de entradas que has planeado, cuánto puede moverse el precio en contra antes del stop-out y qué probabilidad tiene el plan de llegar al objetivo sin tocar ese colchón.",
  "xmPresets": "Escenarios",
  "xmPresetPyramid": "Piramidar bien",
  "xmPresetBlocked": "El tramo que no entra",
  "xmPresetAverage": "Promediar a la baja",
  "xmPresetTaper": "Tramos decrecientes",
  "xmSymbol": "Instrumento",
  "xmSymbolHelp": "El tamaño de contrato sale del catálogo del proyecto, no de un campo suelto: un lote de oro son 100 onzas y uno de plata 5.000. Cambiarlo cambia todas las cifras de abajo.",
  "xmBalance": "Saldo",
  "xmBalanceHelp": "Dinero realizado en la cuenta, sin el flotante. Es el punto de partida del equity y, en cruzado, respalda TODAS las posiciones a la vez.",
  "xmLeverage": "Apalancamiento",
  "xmLeverageHelp": "El divisor del margen. Cambia mucho lo que puedes ABRIR y casi nada lo que puedes SOSTENER: compáralo con las dos cifras de tamaño defendible del final.",
  "xmEntry": "Precio del primer tramo",
  "xmEntryHelp": "Precio al que entra el peldaño 1. Los demás se colocan a partir de él con la separación y el sentido que elijas.",
  "xmLots": "Lotes por tramo",
  "xmLotsHelp": "Tamaño del primer peldaño. Con un decrecimiento por debajo de 1, cada tramo siguiente es una fracción del anterior.",
  "xmSpacing": "Separación entre tramos",
  "xmSpacingHelp": "Distancia de precio entre un peldaño y el siguiente, en unidades del instrumento. Es el campo que decide si el plan entra o no: con separación estrecha el flotante no crece a tiempo de pagar el margen del tramo siguiente.",
  "xmRungs": "Número de tramos",
  "xmRungsHelp": "Cuántos peldaños tiene la escalera, hasta 40.",
  "xmTaper": "Decrecimiento",
  "xmTaperHelp": "Cada tramo multiplica al anterior por este factor. 1 son tramos iguales; 0,6 es piramidación clásica, con cada añadido más pequeño que el previo.",
  "xmTarget": "Objetivo",
  "xmTargetHelp": "Precio al que cerrarías. Sirve para el equity final y para la probabilidad de llegar sin tocar el colchón; si lo pones del lado perdedor, esa probabilidad no se calcula, porque no habría nada que recorrer a favor.",
  "xmStopOut": "Stop-out (%)",
