  "xmTableNote": "«Margen que pide» es la DIFERENCIA de margen usado antes y después del tramo, no lotes por margen unitario: así sale bien también cuando el tramo va en contra y reduce la exposición neta. «Por punto» es lo que mueve la cuenta cada unidad de precio con lo que ya está abierto.",
  "xmCurveTitle": "Margen libre según el precio",
