  "aboutMissionP1": "Las herramientas profesionales de análisis de opciones han estado históricamente reservadas a instituciones con presupuestos de seis cifras. Terminales Bloomberg, software propietario, modelos internos — todo fuera del alcance del trader independiente.",
  "aboutMissionP2": "Creamos TradingCalculator.pro para cambiar eso. Tomamos los modelos matemáticos exactos — Black-Scholes, griegas completas, análisis de volatilidad implícita — y los hicimos accesibles desde cualquier navegador, sin instalaciones, sin licencias corporativas.",
