  "beTableNet": "Con tus costes",
  "beNote": "Un margen por debajo de 5 puntos sobre el equilibrio no es ventaja demostrada: con menos de 100 operaciones registradas es indistinguible del azar. Y un equilibrio por encima del 100 % significa que con esos costes ese ratio no puede ganar ni acertando siempre.",
  "lsTitle": "Rachas de pérdidas",
  "lsDesc": "Cuántas pérdidas seguidas son normales con tu acierto. Saberlo antes evita abandonar un sistema sano en la séptima.",
