  "lsMaxExpectedHint": "Pérdidas seguidas que cabe esperar en ese número de operaciones. No es un techo: es el valor típico.",
  "lsHeadline": "En {n} operaciones, perder {k} seguidas alguna vez tiene un {p} de probabilidad. Es lo normal, no una señal de que el sistema se ha roto.",
  "lsTableTitle": "Probabilidad por longitud de racha",
