  "advTailRatio": "Ratio de colas",
  "advTailRatioHint": "Percentil 95 dividido por el percentil 5 en valor absoluto. Por debajo de 1, tus pérdidas extremas son mayores que tus ganancias extremas. Necesita 20 operaciones.",
  "perfTabValidation": "Validación",
  "btvTitle": "Backtest validado",
  "btvDesc": "Una curva de equity bonita la produce cualquiera probando combinaciones hasta que sale. Esto hace lo que casi nadie: aparta un trozo del histórico que la búsqueda no toca, lo evalúa UNA vez, y descuenta el resultado por cuántas combinaciones probaste. Los costes son obligatorios, no un extra.",
